root.style.setProperty('--accd','rgba('+rgb+',.12)');
root.style.setProperty('--accb','rgba('+rgb+',.3)');

/* HEADER */
g('us-name').textContent=d.name||'Unnamed';
g('us-avatar-mono').textContent=(d.name||'?').trim().charAt(0).toUpperCase();
if(d.avatar){
  var avImg=g('us-avatar-img');
  avImg.src='https://files.catbox.moe/'+d.avatar;
  avImg.style.display='block';
  avImg.onerror=function(){this.style.display='none'};
}
