g('hp-fill').style.width=pct(hp.cur,hp.max)+'%';
g('hp-val').textContent=esc(hp.cur)+' / '+esc(hp.max);
g('st-fill').style.width=pct(st.cur,st.max)+'%';
g('st-val').textContent=esc(st.cur)+' / '+esc(st.max);

/* CONDITIONS */
var condEl=g('conditions-badges');
var conds=d.conditions||[];
condEl.innerHTML=conds.length?conds.map(function(c){return '<span class="badge cond">'+esc(c)+'</span>';}).join(''):'<span class="badge none">Normal</span>';

/* SKILLS */
var skEl=g('skills-list');
var skills=d.skills||[];
if(skills.length){
  skEl.innerHTML=skills.map(function(s){
    var lvl=s.level||0;var max=s.maxLevel||5;
