  }).join('');
}else{
  skEl.innerHTML='<div class="empty-note">No skills recorded.</div>';
}

/* INVENTORY */
var invEl=g('inv-list');
var inv=d.inventory||[];
if(inv.length){
  var gr={};var order=[];
  inv.forEach(function(it){
    var c=it.category||'General';
