  var h='';
  order.forEach(function(cat){
    h+='<div class="cat-block"><div class="cat-lbl">'+esc(cat)+'</div>';
    gr[cat].forEach(function(it){
      h+='<div class="item-row"><div class="item-dot"></div><div>'+
        '<span class="item-nm">'+esc(it.name||'—')+'</span>'+
        '<span class="item-qty">×'+esc(it.qty||1)+'</span>'+
        (it.desc?'<div class="item-desc">'+esc(it.desc)+'</div>':'')+
      '</div></div>';
    });
    h+='</div>';
  });
  invEl.innerHTML=h;
