  if(v>=30)return 'var(--warn)';
  return 'var(--bad)';
}
var relEl=g('rel-list');
var rels=d.relationships||[];
if(rels.length){
  relEl.innerHTML=rels.map(function(r){
    var col=statusColor(r.closeness);
    var initial=(r.name||'?').trim().charAt(0).toUpperCase();
    var avatarInner=esc(initial)+(r.avatar?
      '<img src="https://files.catbox.moe/'+esc(r.avatar)+'" onerror="this.style.display=\'none\'">':'');
    return '<div class="us-card">'+
      '<div class="rel-top">'+
        '<div class="rel-avatar">'+avatarInner+'</div>'+
        '<div class="rel-nm">'+esc(r.name||'—')+'</div>'+
        (r.status?'<span class="rel-status" style="color:'+col+';background:'+col+'1E">'+esc(r.status)+'</span>':'')+
      '</div>'+
      '<div class="rel-bar-wrap"><div class="rel-bar-track"><div class="rel-bar-fill" style="width:'+(r.closeness||0)+'%"></div></div>'+
      '<div class="rel-bar-nums"><span class="rel-bar-val">Closeness '+(r.closeness!=null?r.closeness:0)+'/100</span></div></div>'+
      (r.opinion?'<div class="opinion-box"><div class="opinion-lbl">Their View of You</div><div class="opinion-txt">'+esc(r.opinion)+'</div></div>':'')+
      (r.note?'<div class="rel-note">'+esc(r.note)+'</div>':'')+
