function evtColor(s){
  s=(s||'').toLowerCase();
  if(s==='completed')return 'var(--good)';
  if(s==='ongoing')return 'var(--acc)';
  if(s==='cancelled')return 'var(--mu)';
  return 'var(--warn)'; // upcoming / default
}
var evtEl=g('events-list');
var events=d.events||[];
if(events.length){
  evtEl.innerHTML=events.map(function(e,i){
