/* TABS + COLLAPSE */
document.querySelectorAll('.ustab').forEach(function(t){
  t.addEventListener('click',function(){
    var target=this.getAttribute('data-t');
    document.querySelectorAll('.ustab').forEach(function(x){x.classList.toggle('on',x===t)});
    document.querySelectorAll('.uspane').forEach(function(p){p.classList.toggle('on',p.getAttribute('data-p')===target)});
  });
});
var head=g('ushead');
if(head)head.addEventListener('click',function(){g('uswin').classList.toggle('closed')});
})();
</script>
